@pytest.mark.parametrize("status_code, expected_response", [
    (200, "Successful operation"),
    (400, "Invalid ID supplied"),
    (404, "Pet not found"),
    (422, "Validation exception"),
])
def test_update_pet(api_client: ApiClient, valid_api_key, pet_payload, status_code, expected_response):
    """Test updating an existing pet with various response scenarios."""
    headers = {
        "Authorization": f"Bearer {valid_api_key}",
        "Content-Type": "application/json"
    }
    response = api_client.api_helper.make_request(
        endpoint="pet",
        method='PUT',
        headers=headers,
        params=None,
        data=pet_payload
    )
    assert response.status_code == status_code
    if status_code == 200:
        assert SchemaValidator().validate_schema_pet(response.json())
    else:
        assert expected_response in response.text

